using ChartForgeX.Interactivity.Html;
using ChartForgeX.Typography;
internal static class NativeCompleteCartesianValueExamples {
    internal static void Write(string output,string[] args){var font=NativeFallbackRadialExamples.RequiredFont(args,"--primary-font");FontRegistry.Register("Owned complete-value font",font);Directory.CreateDirectory(output);var renderer=new HtmlInteractiveChartRenderer();foreach(var variant in NativeCompleteCartesianValueRecipe.Variants)foreach(var width in new[]{390,760}){var mode=width==390?VisualThemeMode.Light:VisualThemeMode.Dark;var from=renderer.PrepareSection(NativeCompleteCartesianValueRecipe.Create(variant,30,width,mode,"Owned complete-value font"));var to=renderer.PrepareSection(NativeCompleteCartesianValueRecipe.Create(variant,40,width,mode,"Owned complete-value font"));var payload=renderer.PrepareNativeTransitionJson(from,to,new HtmlNativeTransitionOptions(HtmlNativeTransitionEffect.Values,5));var prefix=Path.Combine(output,"native-complete-cartesian-"+variant+"-"+width);File.WriteAllText(prefix+".from.html",from.Html);File.WriteAllText(prefix+".to.html",to.Html);File.WriteAllText(prefix+".transition.json",payload);File.WriteAllText(prefix+".from.svg",from.PreparedVisual.ToSvg());File.WriteAllBytes(prefix+".from.png",from.PreparedVisual.ToPng());File.WriteAllText(prefix+".to.svg",to.PreparedVisual.ToSvg());File.WriteAllBytes(prefix+".to.png",to.PreparedVisual.ToPng());File.WriteAllText(prefix+".program.cs",ExampleRecipeSource.EmitNativeCompleteCartesianValue(variant,width,mode));}}
}
